'use strict';

const defaultLogger = require('@yandex-int/yandex-logger')({
    name: 'line-logger (default)',
    streams: [
        {
            level: 'info',
            stream: require('@yandex-int/yandex-logger/streams/line')(),
        },
    ],
});

defaultLogger.info('Log info message');
defaultLogger.error('Log %s message by %s', 'error', 'cap');

const logger = require('@yandex-int/yandex-logger')({
    name: 'line-logger',
    streams: [
        {
            level: 'info',
            stream: require('@yandex-int/yandex-logger/streams/line')({
                stream: process.stdout,
                template: [
                    '{{date}} {{levelName}}: {{msg}}',
                    '{{#user}}\nUser: {{userData}}{{/user}}',
                    '{{#err}}\n{{err.stack}}{{/err}}',
                ].join(''),
                resolvers: {
                    date: record => record.date.toISOString(),
                    userData: record => {
                        let user = record.user;
                        return `id=${user.uid}; login=${user.login}`;
                    },
                },
            }),
        },
    ],
});

logger.info('Simple message');
logger.info('Simple message with %s', 'placeholder');
logger.info({
    user: { login: 'yndx-robot', name: 'Vasya.Pupkin' },
}, 'Complex message');

let entry = require('./entry');
logger.error(entry, 'Complex message with error');
